CREATE OR REPLACE FUNCTION public.operator_edit_draft_body(p_gate text, p_draft_id uuid, p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare n int;
begin
  if not operator_gate_ok(p_gate) then
    return jsonb_build_object('ok', false, 'error', 'bad_gate');
  end if;
  if p_body is null or length(trim(p_body)) = 0 then
    return jsonb_build_object('ok', false, 'error', 'empty_body');
  end if;
  update carousel_drafts
    set post_body = p_body,
        agent_log = coalesce(agent_log, '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
          'ts', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
          'agent', 'Operator', 'body', 'Copy edited on the ops panel', 'source', 'dashboard'
        ))
    where id = p_draft_id and client_id is not null and status in ('review','scheduled');
  get diagnostics n = row_count;
  if n = 0 then
    return jsonb_build_object('ok', false, 'error', 'not_editable');
  end if;
  return jsonb_build_object('ok', true);
end; $function$

CREATE OR REPLACE FUNCTION public.operator_set_board_visible(p_gate text, p_draft_id uuid, p_visible boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_client text; v_status text; v_req bigint;
begin
  if not operator_gate_ok(p_gate) then
    return jsonb_build_object('ok', false, 'error', 'bad_gate');
  end if;
  select client_id, status into v_client, v_status
  from carousel_drafts where id = p_draft_id;
  if v_client is null then
    return jsonb_build_object('ok', false, 'error', 'draft_not_found');
  end if;
  if p_visible and v_status <> 'review' then
    return jsonb_build_object('ok', false, 'error', 'not_in_review');
  end if;
  update carousel_drafts set board_visible = p_visible, updated_at = now()
  where id = p_draft_id;
  select net.http_post(
    url := 'https://n8n.ivanmanfredi.com/webhook/client-board-queue-sync?k=6098d6f092c50f5f1894fd61',
    body := jsonb_build_object('client_id', v_client),
    headers := '{"Content-Type":"application/json"}'::jsonb
  ) into v_req;
  return jsonb_build_object('ok', true, 'id', p_draft_id,
    'board_visible', p_visible, 'client_id', v_client, 'sync_request_id', v_req);
end;
$function$
